function.arguments:
{"command": "# Check if power management is persistent across reboots
cat /etc/NetworkManager/conf.d/wifi-powersave-off.conf 2>/dev/null || echo "No NM wifi powersave config"

echo "---"

# Check current power management state
iw dev wlp2s0 get power_save 2>&1

echo "---"

# Check the error pattern timing - are they roughly every 5 minutes?
echo "=== Interval between consecutive errors ==="
grep "Telegram network error" ~/.hermes/logs/errors.log | grep "2026-04-30" | head -20 | awk '{
  split($1,date,"-");
  split($2,time,":");
  t = time[1]*3600 + time[2]*60 + time[3];
  if (prev > 0) {
    diff = t - prev;
    printf "%s -> interval: %d seconds (%.1f min)\n", $2, diff, diff/60;
  }
  prev = t;
}'

echo "---"

# Check if there's a keepalive timeout issue - what's the long poll timeout?
grep -i "timeout\|keepalive\|retry\|long.poll" ~/.hermes/logs/agent.log | grep -i telegram | tail -10", "timeout": 15}
